import numpy as np
from scipy.optimize import least_squares
def model_pred(p, form):
    a,w,k=p[0],p[1],p[2]
    e=a*np.exp(-a*np.sqrt(v))
    if form==0: F=[e, t**2, np.cos(w*t)*v]
    if form==1: F=[e, t**2, np.cos(w*t)*x]
    if form==2: F=[e, t**2*x, np.cos(w*t)*v]
    if form==3: F=[e, t**2*v, np.cos(w*t)]
    if form==4: F=[e, t**2, np.cos(w*t)]
    if form==5: F=[e, t**2, np.sin(w*t)*v]
    if form==6: F=[e, t**3, np.cos(w*t)*v]
    return np.column_stack(F)
def solve(form):
    best=None
    for w0 in np.linspace(0.3,4,15):
        for a0 in [0.3,1.0]:
            def resid(p):
                B=model_pred(p,form)
                c=np.linalg.lstsq(B,dv_dt,rcond=None)[0]
                return dv_dt-B@c
            try:
                rr=least_squares(resid,[a0,w0,0])
            except Exception: continue
            nm=np.mean(rr.fun**2)/np.var(dv_dt)
            if best is None or nm<best[0]: best=(nm,np.round(rr.x,4))
    return best
